// Embedded wiki artwork; no runtime image-host dependency.
export const Logo = new Blob([Uint8Array.from(atob(''), character => character.charCodeAt(0))], { type: 'image/png' })
export const TransparentLogo = new Blob([Uint8Array.from(atob(''), character => character.charCodeAt(0))], { type: 'image/png' })
export const Eyes = new Blob([Uint8Array.from(atob(''), character => character.charCodeAt(0))], { type: 'image/png' })
